diff --git a/packages/workflow/src/expressions/native-evaluation/evaluator.ts b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
index 6883c56c6..f8f97b03e 100644
--- a/packages/workflow/src/expressions/native-evaluation/evaluator.ts
+++ b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
@@ -346,6 +346,19 @@ function assertConcatWeight(receiver: unknown[], args: unknown[]): void {
 	if (weight > MAX_RESULT_LENGTH) throw new EngineFallbackError();
 }

+/**
+ * Array methods that compare every element against an argument. Comparing
+ * strings costs their length, so element count under-charges: the receiver's
+ * content is the work, like an extension call.
+ */
+const COMPARES_ELEMENTS = new Set(['includes', 'indexOf', 'lastIndexOf']);
+
+function comparisonWeight(receiver: unknown[]): number {
+	const weight = contentWeight(receiver, MAX_RESULT_LENGTH);
+	if (weight > MAX_RESULT_LENGTH) throw new EngineFallbackError();
+	return weight;
+}
+
 function evalReceiver(
 	node: Extract<SimpleNode, { kind: 'call' | 'iterate' }>,
 	env: Env,
@@ -391,6 +404,9 @@ function evalCall(node: Extract<SimpleNode, { kind: 'call' }>, env: Env): unknow
 		if (node.method === 'concat') assertConcatWeight(receiver, args);
 	}
 	env.charge(preflightSize(receiver, node.method, args));
+	if (isArray(receiver) && COMPARES_ELEMENTS.has(node.method)) {
+		env.charge(comparisonWeight(receiver));
+	}

 	return bounded(method.apply(receiver, args));
 }
