@@ -642,6 +642,18 @@ describe('Expression - fast native evaluation parity', () => {
 			).toEqual({ handled: false });
 		});

+		test('array comparison methods are charged by element content', () => {
+			const hay = ['x'.repeat(MAX_RESULT_LENGTH - 10)];
+			const visits = Math.ceil(MAX_WORK / MAX_RESULT_LENGTH) + 1;
+			const few = new Array<string>(2).fill('y');
+			const many = new Array<string>(visits).fill('y');
+			for (const method of ['includes', 'indexOf', 'lastIndexOf']) {
+				const expression = `{{ $json.many.some(n => $json.hay.${method}(n) === 7) }}`;
+				expect(nativeOn(expression, { $json: { many, hay } })).toEqual({ handled: false });
+				expect(nativeOn(expression, { $json: { many: few, hay } }).handled).toBe(true);
+			}
+		});
+
 		// A `$parameter` read resolves a nested expression in its own evaluation,
